"""Generate browsable knowledge map from the same profiles consumed by ranking."""
from pathlib import Path
import json,html
root=Path(__file__).resolve().parent.parent;profiles=json.loads((root/'data/recipe-profiles.json').read_text());recipes=json.loads((root/'data/recipes.json').read_text());esc=html.escape
parts=[];groups={}
md=['# Recipe mind map','', 'Reviewed 2026-10-20. All 19 recipes share this structure: intent → subjects → light → palette → observed references → cautions → related choices → preview assumptions. Source settings remain authoritative; observations are not calibrated transforms.','', '```mermaid','mindmap','  root((Fuji recipes))']
for r in recipes:groups.setdefault(r['settings']['Film simulation'],[]).append(r)
for sim,rs in groups.items():
 md+=['    '+sim]
 for r in rs:md+=['      '+r['name']]
md+=['```','']
for sim,rs in groups.items():
 cards=[]
 for r in rs:
  p=profiles[r['id']];fields=[('Intent',p['intent']),('Subjects',', '.join(p['subjects'])),('Light to consider',', '.join(p['preferredLighting'])),('Palette',', '.join(p['palette'])),('Observed references',p['referenceObservation']),('Caution',p['caution']),('Preview assumptions',p['previewIntent']),('Evidence',p['evidence']+' · '+p['evidenceLimits'])]
  content=''.join('<dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd>' for k,v in fields)
  related=''.join('<p><a href="#'+esc(x['id'])+'">'+esc(next(r['name'] for r in recipes if r['id']==x['id']))+'</a> — '+esc(x['difference'])+'</p>' for x in p['relatedRecipes'])
  cards.append('<details id="'+r['id']+'" data-search="'+esc(json.dumps([r['name'],sim,p],ensure_ascii=False))+'"><summary>'+esc(r['name'])+' <small>'+str(len(r['images']))+' references</small></summary><div class="body"><img src="'+r['images'][0]['url'].lstrip('/')+'" alt="'+esc(r['name'])+' reference"><dl>'+content+'</dl><h3>Related direction</h3>'+related+'<h3>Saved settings</h3><dl>'+''.join('<dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd>' for k,v in r['settings'].items())+'</dl><h3>Evidence register</h3><ul>'+''.join('<li>'+esc(s)+'</li>' for s in p['sources'])+'</ul></div></details>')
  md+=['## '+r['name'],'']+[f'**{k}:** {v}\n' for k,v in fields]+['**Related:** '+p['relatedRecipes'][0]['difference'],'']
 parts.append('<section><h2>'+esc(sim)+'</h2>'+''.join(cards)+'</section>')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fuji recipe mind map</title><style>body{background:#101719;color:#eee9df;font:17px/1.6 system-ui;margin:0;padding:24px}main{max-width:1060px;margin:auto}a{color:#dbb780}h1{font-size:clamp(30px,5vw,48px);line-height:1.1}h2{font-size:22px;color:#dbb780}input{box-sizing:border-box;width:100%;font:inherit;background:#1c2729;color:inherit;border:1px solid #647275;padding:14px;border-radius:10px;position:sticky;top:10px}section{border-left:2px solid #8b7050;padding-left:20px}details{background:#1b2426;border:1px solid #3a4545;border-radius:12px;margin:12px 0;scroll-margin-top:90px}summary{cursor:pointer;font-size:21px;font-weight:700;padding:18px}small{display:block;font-size:13px;font-weight:400;color:#bdc5c2}.body{padding:0 20px 24px}img{width:min(100%,300px);border-radius:8px}dt{font-weight:700;color:#dbb780;margin-top:14px}dd{margin:0}button{font:inherit;color:inherit;background:#263335;border:1px solid #647275;border-radius:8px;padding:10px;margin:12px 8px 0 0}li{overflow-wrap:anywhere}[hidden]{display:none}</style><main><a href="./">← Recipe collection</a><h1>Recipe mind map</h1><p>19 recipes · Intent, light, color and the reason to choose each.</p><p>Follow a simulation branch, open a recipe, then compare related directions. These records inform scene ranking. Previews remain approximations; reference photos do not establish an exact camera transform.</p><input id="search" type="search" aria-label="Search recipe knowledge" placeholder="Search recipes, skin, wood, mist, light…"><button id="expand">Open all</button><button id="collapse">Close all</button>'''+''.join(parts)+'''<p>Updated 20 October 2026. New recipes must extend the same evidence record before becoming recommendation candidates.</p></main><script>const nodes=[...document.querySelectorAll('details')];document.querySelector('#search').oninput=e=>{const q=e.target.value.toLowerCase();nodes.forEach(n=>n.hidden=!n.dataset.search.toLowerCase().includes(q));document.querySelectorAll('section').forEach(s=>s.hidden=![...s.querySelectorAll('details')].some(n=>!n.hidden))};document.querySelector('#expand').onclick=()=>nodes.filter(n=>!n.hidden).forEach(n=>n.open=true);document.querySelector('#collapse').onclick=()=>nodes.forEach(n=>n.open=false);function reveal(){const n=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(n?.tagName==='DETAILS'){n.hidden=false;n.open=true;n.closest('section').hidden=false;n.scrollIntoView()}}window.onhashchange=reveal;reveal();</script></html>'''
(root/'public/recipe-mind-map.html').write_text(page);(root/'docs/recipe-mind-map.md').write_text('\n'.join(md)+'\n')
print('Generated connected mind map for',len(profiles),'recipes')
